import { execFile } from "node:child_process";
import { lstat, readFile, readdir } from "node:fs/promises";
import { dirname, isAbsolute, relative, resolve, sep } from "node:path";
import { promisify } from "node:util";
import { fileURLToPath, pathToFileURL } from "node:url";

const defaultRepoRoot = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const execFileAsync = promisify(execFile);
const GENERATED_MARKER = "Generated by GG Coder /setup generated-audit v1";

export const PROTECTED_RELATIVE_PATHS = [
  ".gg",
  ".env",
  ".npmrc",
  "node_modules",
  "gg-app/src-tauri/binaries",
];

function lexicalCompare(left, right) {
  return left < right ? -1 : left > right ? 1 : 0;
}

function toDisplayPath(path) {
  return path.split(sep).join("/");
}

function displayPath(repoRoot, path) {
  return toDisplayPath(relative(repoRoot, path));
}

function isSameOrDescendant(path, parent) {
  const rel = relative(parent, path);
  return rel === "" || (!rel.startsWith(`..${sep}`) && rel !== ".." && !isAbsolute(rel));
}

function safePath(repoRoot, literalPath) {
  if (
    typeof literalPath !== "string" ||
    literalPath.length === 0 ||
    isAbsolute(literalPath) ||
    literalPath.includes("\0") ||
    literalPath
      .split(/[\\/]/)
      .some((segment) => segment === "" || segment === "." || segment === "..") ||
    /[*?\[\]{}]/.test(literalPath)
  ) {
    throw new Error(`Refusing non-literal repository path: ${String(literalPath)}`);
  }

  const absolute = resolve(repoRoot, ...literalPath.split("/"));
  if (!isSameOrDescendant(absolute, repoRoot) || absolute === repoRoot) {
    throw new Error(`Refusing path outside the repository: ${literalPath}`);
  }
  return absolute;
}

export function assertProtectedPathsExcluded(repoRoot, paths) {
  const protectedPaths = PROTECTED_RELATIVE_PATHS.map((path) => safePath(repoRoot, path));
  for (const path of paths) {
    if (
      protectedPaths.some(
        (protectedPath) =>
          isSameOrDescendant(path, protectedPath) || isSameOrDescendant(protectedPath, path),
      )
    ) {
      throw new Error(`Refusing to select protected path: ${displayPath(repoRoot, path)}`);
    }
  }
}

async function lstatIfPresent(path) {
  try {
    return await lstat(path);
  } catch (error) {
    if (error && typeof error === "object" && error.code === "ENOENT") return undefined;
    throw error;
  }
}

async function readTextIfPresent(path) {
  try {
    return await readFile(path, "utf8");
  } catch (error) {
    if (error && typeof error === "object" && error.code === "ENOENT") return undefined;
    throw error;
  }
}

async function readJsonIfPresent(path) {
  const text = await readTextIfPresent(path);
  if (text === undefined) return undefined;
  try {
    return JSON.parse(text);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Unsupported invalid JSON in ${path}: ${detail}`, { cause: error });
  }
}

function workspacePatterns(rootManifest, workspaceText) {
  const patterns = [];
  const declared = rootManifest?.workspaces;
  if (Array.isArray(declared)) patterns.push(...declared);
  if (declared && Array.isArray(declared.packages)) patterns.push(...declared.packages);

  if (workspaceText) {
    let insidePackages = false;
    for (const line of workspaceText.split(/\r?\n/)) {
      if (/^packages\s*:/.test(line)) {
        insidePackages = true;
        continue;
      }
      if (insidePackages && /^\S/.test(line)) break;
      const match = insidePackages ? line.match(/^\s*-\s*["']?([^"'#]+?)["']?\s*$/) : undefined;
      if (match) patterns.push(match[1].trim());
    }
  }

  return [...new Set(patterns.filter((pattern) => typeof pattern === "string"))].sort(
    lexicalCompare,
  );
}

async function directWorkspaceRoots(repoRoot, patterns, unsupported) {
  const roots = [];
  for (const rawPattern of patterns) {
    const pattern = rawPattern.replaceAll("\\", "/").replace(/^\.\//, "");
    if (pattern.startsWith("!") || pattern.includes("..")) {
      unsupported.push(`Unsupported workspace declaration: ${rawPattern}`);
      continue;
    }

    if (!pattern.includes("*")) {
      const root = safePath(repoRoot, pattern);
      const stat = await lstatIfPresent(root);
      if (stat?.isDirectory()) roots.push(root);
      continue;
    }

    if (!pattern.endsWith("/*") || pattern.slice(0, -2).includes("*")) {
      unsupported.push(`Unsupported non-direct workspace declaration: ${rawPattern}`);
      continue;
    }

    const parentLiteral = pattern.slice(0, -2);
    const parent = safePath(repoRoot, parentLiteral);
    const parentStat = await lstatIfPresent(parent);
    if (!parentStat?.isDirectory()) continue;
    const entries = await readdir(parent, { withFileTypes: true });
    entries.sort((left, right) => lexicalCompare(left.name, right.name));
    for (const entry of entries) {
      if (entry.isDirectory() && !entry.isSymbolicLink()) roots.push(resolve(parent, entry.name));
    }
  }

  return [...new Set(roots)].sort((left, right) =>
    lexicalCompare(displayPath(repoRoot, left), displayPath(repoRoot, right)),
  );
}

function collectOutputRoots(value, roots) {
  if (typeof value === "string") {
    const normalized = value.replaceAll("\\", "/").replace(/^\.\//, "");
    if (!normalized || normalized.startsWith("../") || isAbsolute(normalized)) return;
    const first = normalized.split("/")[0];
    if (first && !first.includes(".") && first !== "src" && first !== "node_modules")
      roots.add(first);
    return;
  }
  if (Array.isArray(value)) {
    for (const item of value) collectOutputRoots(item, roots);
    return;
  }
  if (value && typeof value === "object") {
    for (const item of Object.values(value)) collectOutputRoots(item, roots);
  }
}

function packageOutputRoots(manifest) {
  const roots = new Set();
  for (const key of ["main", "module", "types", "bin", "exports"]) {
    collectOutputRoots(manifest?.[key], roots);
  }
  return [...roots].sort(lexicalCompare);
}

function artifact(path, evidence, evidenceFiles) {
  return {
    path,
    evidence: [...new Set(evidence)].sort(lexicalCompare),
    evidenceFiles: [...new Set(evidenceFiles)].sort(lexicalCompare),
  };
}

function addArtifact(targets, id, item) {
  const target = targets.get(id) ?? { id, artifacts: [] };
  const existing = target.artifacts.find((candidate) => candidate.path === item.path);
  if (existing) {
    existing.evidence = [...new Set([...existing.evidence, ...item.evidence])].sort(lexicalCompare);
    existing.evidenceFiles = [...new Set([...existing.evidenceFiles, ...item.evidenceFiles])].sort(
      lexicalCompare,
    );
  } else {
    target.artifacts.push(item);
    target.artifacts.sort((left, right) => lexicalCompare(left.path, right.path));
  }
  targets.set(id, target);
}

function simpleCargoTargetDir(configText) {
  if (!configText) return undefined;
  const matches = [...configText.matchAll(/^\s*target-dir\s*=\s*["']([^"']+)["']\s*$/gm)];
  if (matches.length !== 1) return undefined;
  const value = matches[0][1].replaceAll("\\", "/");
  if (!value || value.includes("..") || isAbsolute(value) || /[*?\[\]{}]/.test(value))
    return undefined;
  return value;
}

function cacheLocation(script) {
  const explicit = script.match(/--cache-location(?:=|\s+)(?:["']([^"']+)["']|([^\s]+))/);
  if (explicit) return (explicit[1] ?? explicit[2]).replaceAll("\\", "/");
  return /(?:^|\s)--cache(?:\s|$)/.test(script) ? ".eslintcache" : undefined;
}

export async function discoverGenerated({ repoRoot = defaultRepoRoot } = {}) {
  const rootManifestPath = resolve(repoRoot, "package.json");
  const rootManifest = await readJsonIfPresent(rootManifestPath);
  const workspaceFile = resolve(repoRoot, "pnpm-workspace.yaml");
  const workspaceText = await readTextIfPresent(workspaceFile);
  const unsupported = [];
  const patterns = workspacePatterns(rootManifest, workspaceText);
  const packageRoots = await directWorkspaceRoots(repoRoot, patterns, unsupported);
  const targets = new Map();
  const packageArtifacts = [];
  const claimedPaths = new Set();

  const manifests = [];
  if (rootManifest)
    manifests.push({ root: repoRoot, manifest: rootManifest, file: "package.json" });
  for (const root of packageRoots) {
    const file = `${displayPath(repoRoot, root)}/package.json`;
    const manifest = await readJsonIfPresent(resolve(root, "package.json"));
    if (manifest) manifests.push({ root, manifest, file });
  }

  for (const entry of manifests) {
    const scripts = entry.manifest.scripts ?? {};
    const buildScript = typeof scripts.build === "string" ? scripts.build : "";
    const rootPath = displayPath(repoRoot, entry.root);

    if (buildScript && /(^|[\s;&])vite\s+build(?:\s|$)/.test(buildScript)) {
      const tauriFile = `${rootPath}/src-tauri/tauri.conf.json`;
      const tauriConfig = await readJsonIfPresent(
        resolve(entry.root, "src-tauri", "tauri.conf.json"),
      );
      const frontendDist = tauriConfig?.build?.frontendDist;
      const distLiteral = `${rootPath}/dist`;
      const evidence = [`${entry.file} build script runs vite build`];
      const evidenceFiles = [entry.file];
      if (frontendDist === "../dist") {
        evidence.push(`${tauriFile} build.frontendDist points to ../dist`);
        evidenceFiles.push(tauriFile);
      }
      addArtifact(targets, "web", artifact(distLiteral, evidence, evidenceFiles));
      claimedPaths.add(distLiteral);
    }

    for (const [scriptName, script] of Object.entries(scripts)) {
      if (typeof script !== "string" || !script.includes("--cache")) continue;
      const location = cacheLocation(script);
      if (
        !location ||
        location.includes("..") ||
        isAbsolute(location) ||
        /[*?\[\]{}]/.test(location)
      ) {
        unsupported.push(`Unsupported cache location in ${entry.file} script ${scriptName}`);
        continue;
      }
      const literal = rootPath === "" ? location : `${rootPath}/${location}`;
      addArtifact(
        targets,
        "cache",
        artifact(literal, [`${entry.file} ${scriptName} script enables this cache`], [entry.file]),
      );
      claimedPaths.add(literal);
    }

    if (entry.root !== repoRoot && buildScript) {
      for (const outputRoot of packageOutputRoots(entry.manifest)) {
        const literal = `${rootPath}/${outputRoot}`;
        packageArtifacts.push(
          artifact(
            literal,
            [`${entry.file} build script and package entry points declare ${outputRoot}`],
            [entry.file],
          ),
        );
      }
    }

    const tauriRoot = resolve(entry.root, "src-tauri");
    const cargoFile = `${rootPath}/src-tauri/Cargo.toml`;
    const tauriFile = `${rootPath}/src-tauri/tauri.conf.json`;
    const ignoreFile = `${rootPath}/src-tauri/.gitignore`;
    const cargoText = await readTextIfPresent(resolve(tauriRoot, "Cargo.toml"));
    const tauriConfig = await readJsonIfPresent(resolve(tauriRoot, "tauri.conf.json"));
    const ignoreText = await readTextIfPresent(resolve(tauriRoot, ".gitignore"));

    if (cargoText && tauriConfig) {
      const cargoConfigFile = `${rootPath}/.cargo/config.toml`;
      const cargoConfigText = await readTextIfPresent(resolve(entry.root, ".cargo", "config.toml"));
      const configuredTarget = simpleCargoTargetDir(cargoConfigText);
      if (cargoConfigText && !configuredTarget && /target-dir/.test(cargoConfigText)) {
        unsupported.push(`Unsupported dynamic Cargo target-dir in ${cargoConfigFile}`);
      }
      const targetDir = configuredTarget ?? "src-tauri/target";
      const targetLiteral = `${rootPath}/${targetDir}`;
      const targetEvidence = [`${cargoFile} declares the Tauri Cargo package`];
      const targetFiles = [cargoFile, tauriFile];
      if (configuredTarget) {
        targetEvidence.push(`${cargoConfigFile} declares target-dir ${configuredTarget}`);
        targetFiles.push(cargoConfigFile);
      } else if (/^\/target\/?$/m.test(ignoreText ?? "")) {
        targetEvidence.push(`${ignoreFile} marks Cargo target output`);
        targetFiles.push(ignoreFile);
      }
      addArtifact(targets, "tauri", artifact(targetLiteral, targetEvidence, targetFiles));
      claimedPaths.add(targetLiteral);

      if (/^\/gen\/schemas\/?$/m.test(ignoreText ?? "")) {
        const schemasLiteral = `${rootPath}/src-tauri/gen/schemas`;
        addArtifact(
          targets,
          "tauri-schemas",
          artifact(
            schemasLiteral,
            [`${tauriFile} declares Tauri configuration`, `${ignoreFile} marks generated schemas`],
            [tauriFile, ignoreFile],
          ),
        );
        claimedPaths.add(schemasLiteral);
      }

      const resources = Array.isArray(tauriConfig?.bundle?.resources)
        ? tauriConfig.bundle.resources
        : [];
      if (
        resources.some(
          (value) => typeof value === "string" && value.replaceAll("\\", "/") === "sidecar/",
        ) &&
        /^\/sidecar\/?$/m.test(ignoreText ?? "") &&
        typeof scripts["bundle:sidecar"] === "string"
      ) {
        const sidecarLiteral = `${rootPath}/src-tauri/sidecar`;
        addArtifact(
          targets,
          "sidecar-deps",
          artifact(
            sidecarLiteral,
            [
              `${entry.file} bundle:sidecar script generates the staged sidecar`,
              `${tauriFile} bundles sidecar/ as a resource`,
              `${ignoreFile} marks the staged sidecar output`,
            ],
            [entry.file, tauriFile, ignoreFile],
          ),
        );
        claimedPaths.add(sidecarLiteral);
      }
    }
  }

  for (const item of packageArtifacts) {
    if (!claimedPaths.has(item.path)) addArtifact(targets, "packages", item);
  }

  const resultTargets = [...targets.values()]
    .filter((target) => target.artifacts.length > 0)
    .sort((left, right) => lexicalCompare(left.id, right.id));
  for (const target of resultTargets) {
    const absolutePaths = target.artifacts.map((item) => safePath(repoRoot, item.path));
    assertProtectedPathsExcluded(repoRoot, absolutePaths);
  }

  return { targets: resultTargets, unsupported: unsupported.sort(lexicalCompare) };
}

export function renderCleanupMarkdown(inspection) {
  const lines = [
    "---",
    "name: cleanup",
    "description: Audit generated artifacts without changing the working tree",
    "---",
    "",
    `<!-- ${GENERATED_MARKER} -->`,
    "",
    "This command is read-only: it reports generated artifacts and must never delete or alter them.",
    "",
  ];

  if (inspection.targets.length === 0) {
    lines.push(
      "No generated-artifact targets were detected.",
      "",
      "Run `node scripts/audit-generated.mjs --inspect` and report the empty target list and any unsupported configuration.",
    );
  } else {
    lines.push("Require exactly one target from this evidence-backed list:", "");
    for (const target of inspection.targets) {
      lines.push(`- \`${target.id}\``);
      for (const item of target.artifacts) {
        lines.push(
          `  - \`${item.path}\` — ${item.evidence.join("; ")} (evidence: ${item.evidenceFiles.join(", ")})`,
        );
      }
    }
    lines.push(
      "",
      "Run `node scripts/audit-generated.mjs <target>` for the selected target and report its complete output.",
    );
  }

  lines.push(
    "Treat `Refusing to audit ...` and every Git/spawn error as a failed audit.",
    "Run `git status --short` before and after only to confirm the audit made no changes.",
    "Do not follow the audit with deletion, cleanup, or any other artifact mutation.",
    "",
  );
  return lines.join("\n");
}

export async function inspectGenerated(options = {}) {
  const inspection = await discoverGenerated(options);
  return { ...inspection, cleanupMarkdown: renderCleanupMarkdown(inspection) };
}

function refusal(repoRoot, selectedPath, reasonPath, reason) {
  return new Error(
    `Refusing to audit ${displayPath(repoRoot, selectedPath)}: ${reason} at ${displayPath(repoRoot, reasonPath)}`,
  );
}

async function assertSafePathSegments(repoRoot, selectedPath) {
  const segments = relative(repoRoot, selectedPath).split(sep);
  let current = repoRoot;
  for (const segment of segments) {
    current = resolve(current, segment);
    const stat = await lstatIfPresent(current);
    if (!stat) return undefined;
    if (stat.isSymbolicLink()) {
      throw refusal(repoRoot, selectedPath, current, "symbolic link or junction");
    }
  }
  return lstat(selectedPath);
}

async function assertSafeDirectoryTree(repoRoot, selectedPath, directory) {
  const entries = await readdir(directory, { withFileTypes: true });
  entries.sort((left, right) => lexicalCompare(left.name, right.name));
  for (const entry of entries) {
    const child = resolve(directory, entry.name);
    if (entry.name.toLowerCase() === ".git") {
      throw refusal(repoRoot, selectedPath, child, "nested Git repository metadata");
    }
    const stat = await lstat(child);
    if (stat.isSymbolicLink()) {
      throw refusal(repoRoot, selectedPath, child, "symbolic link or junction");
    }
    if (stat.isDirectory()) await assertSafeDirectoryTree(repoRoot, selectedPath, child);
    else if (!stat.isFile())
      throw refusal(repoRoot, selectedPath, child, "unsupported filesystem object");
  }
}

async function inspectAuditPath(repoRoot, path) {
  const stat = await assertSafePathSegments(repoRoot, path);
  if (!stat) return false;
  if (stat.isDirectory()) {
    await assertSafeDirectoryTree(repoRoot, path, path);
    return true;
  }
  if (stat.isFile()) return true;
  throw refusal(repoRoot, path, path, "unsupported filesystem object");
}

async function runGit(repoRoot, args, path, { allowNoMatch = false, input } = {}) {
  try {
    const options = { cwd: repoRoot, encoding: "utf8", shell: false };
    if (input === undefined) {
      const { stdout } = await execFileAsync("git", args, options);
      return stdout;
    }
    return await new Promise((resolvePromise, rejectPromise) => {
      const child = execFile("git", args, options, (error, stdout) => {
        if (error) rejectPromise(error);
        else resolvePromise(stdout);
      });
      child.stdin.end(input);
    });
  } catch (error) {
    if (allowNoMatch && error && typeof error === "object" && error.code === 1) return "";
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Git audit failed for ${path}: ${detail}`, { cause: error });
  }
}

async function gitState(repoRoot, absolutePath) {
  const path = displayPath(repoRoot, absolutePath);
  const trackedOutput = await runGit(repoRoot, ["ls-files", "-z", "--", path], path);
  const ignoreOutput = await runGit(
    repoRoot,
    ["check-ignore", "--no-index", "-v", "-z", "--stdin"],
    path,
    { allowNoMatch: true, input: `${path}\0` },
  );
  const tracked = trackedOutput.split("\0").some(Boolean);
  const fields = ignoreOutput.split("\0");
  const ignored = fields.length >= 4 && fields[2] !== "";
  const ignoreRule = ignored
    ? `${fields[0].split("\\").join("/")}:${fields[1]}:${fields[2]}`
    : undefined;
  return { ignored, ignoreRule, tracked };
}

function formatPathStatus(item, present, state) {
  const fields = [
    `path=${item.path}`,
    `evidence=${item.evidence.join("; ")}`,
    `evidence-files=${item.evidenceFiles.join(",")}`,
    `present=${present ? "yes" : "no"}`,
    `tracked=${state.tracked ? "yes" : "no"}`,
    `ignored=${state.ignored ? "yes" : "no"}`,
  ];
  if (state.ignoreRule) fields.push(`ignore-rule=${state.ignoreRule}`);
  return fields.join(" | ");
}

export async function auditGenerated({ repoRoot = defaultRepoRoot, target, log = console.log }) {
  const inspection = await discoverGenerated({ repoRoot });
  const selected = inspection.targets.find((candidate) => candidate.id === target);
  if (!selected) throw new Error(`Unknown audit target: ${target}`);

  const statuses = [];
  for (const item of selected.artifacts) {
    const path = safePath(repoRoot, item.path);
    const present = await inspectAuditPath(repoRoot, path);
    const state = await gitState(repoRoot, path);
    statuses.push({ item, present, state });
  }

  log(`Generated-artifact audit: ${target}`);
  for (const status of statuses) log(formatPathStatus(status.item, status.present, status.state));
  if (statuses.every(({ present }) => !present))
    log(`(no generated artifacts found for ${target})`);
}

export function parseArgs(argv) {
  const args = argv.filter((arg) => arg !== "--");
  if (args.length === 1 && args[0] === "--inspect") return { inspect: true };
  if (args.length === 1 && (args[0] === "--help" || args[0] === "-h")) return { help: true };
  if (args.some((arg) => arg.startsWith("-"))) {
    throw new Error(`Unknown option: ${args.find((arg) => arg.startsWith("-"))}`);
  }
  if (args.length !== 1) throw new Error("Expected exactly one audit target.");
  return { target: args[0] };
}

async function help() {
  const inspection = await discoverGenerated();
  console.log("Usage: node scripts/audit-generated.mjs --inspect | <target>");
  console.log(`Targets: ${inspection.targets.map((target) => target.id).join(", ") || "none"}`);
  console.log("Safety: reports only; never changes generated artifacts.");
}

async function main() {
  const args = parseArgs(process.argv.slice(2));
  if (args.help) return help();
  if (args.inspect) {
    console.log(JSON.stringify(await inspectGenerated(), null, 2));
    return;
  }
  await auditGenerated({ target: args.target });
}

const isDirectRun =
  process.argv[1] !== undefined && pathToFileURL(resolve(process.argv[1])).href === import.meta.url;

if (isDirectRun) {
  main().catch((error) => {
    console.error(error instanceof Error ? error.message : error);
    console.error("Run with --help to inspect supported targets.");
    process.exitCode = 1;
  });
}
